<template>
  <view class="qw-detail qw-stack">
    <view v-if="ready" class="qw-form">
      <view class="qw-field">
        <wd-cell :title="t('field.demo.topic.parentId')" :value="parentText" />
        <text v-if="errors.parentId" class="qw-field__error">{{ errors.parentId }}</text>
      </view>
      <view class="qw-field">
        <text class="qw-field__label is-required">{{ t('field.demo.topic.title') }}</text>
        <wd-input v-model="form.title" :maxlength="100" clearable />
        <text v-if="errors.title" class="qw-field__error">{{ errors.title }}</text>
      </view>
      <view class="qw-field">
        <text class="qw-field__label">{{ t('field.demo.topic.sortNo') }}</text>
        <wd-input-number
          :model-value="form.sortNo ?? ''"
          :min="0"
          :max="999999"
          allow-null
          @update:model-value="form.sortNo = numOf($event)"
        />
        <text v-if="errors.sortNo" class="qw-field__error">{{ errors.sortNo }}</text>
      </view>
      <view class="qw-field">
        <wd-cell :title="t('field.demo.topic.enabled')" center>
          <wd-switch v-model="form.enabled" />
        </wd-cell>
        <text v-if="errors.enabled" class="qw-field__error">{{ errors.enabled }}</text>
      </view>
      <text v-if="error" class="qw-form__error" role="alert">{{ error }}</text>
      <wd-button
        custom-class="qw-btn qw-btn--primary"
        type="primary"
        block
        :loading="submitting"
        :disabled="submitting"
        @click="submit"
      >
        {{ t('crud.action.save') }}
      </wd-button>
    </view>
    <QwEmpty v-else-if="error" :title="error" />
  </view>
</template>

<script setup lang="ts">
import { computed, reactive, ref, shallowRef, watch } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { type TopicCreate, topicCreate, type TopicVo, type ValidationIssue } from '@qiwu/shared'
import { topicApi } from '@/api/demo/topic'
import QwEmpty from '@/core/components/QwEmpty.vue'
import { fillForm, type Form, numOf } from '@/core/crud'
import { fieldErrors, t } from '@/core/i18n'
import { ApiError, errorText } from '@/core/request'

/**
 * Add / edit page of the topic list (mobile, generated): `?id=` edits that row, else it
 * adds one below `?parentId=` (0: at the top level). The rules: the shared `topicCreate`
 * (the server checks again). The save button shows loading and is disabled while pending.
 */
const id = ref(0)
const ready = ref(false)
const error = ref('')
const submitting = ref(false)
const form = reactive<Form<TopicCreate>>({
  parentId: 0,
  title: '',
  sortNo: 0,
  enabled: true,
})
const issues = shallowRef<ValidationIssue[]>([])
const errors = computed(() => fieldErrors(topicCreate, issues.value))
// once shown, the messages follow the input
watch(form, () => {
  if (issues.value.length) issues.value = topicCreate.safeParse(form).error?.issues ?? []
})
const parentRow = shallowRef<TopicVo>()
const parentText = computed(() => {
  const label = parentRow.value?.title
  if (label) return label
  return form.parentId ? String(form.parentId) : t('crud.tree.topLevel')
})

onLoad(async (query) => {
  id.value = Number(query?.id) || 0
  const name = t('demo.topic.entity')
  uni.setNavigationBarTitle({
    title: t(id.value ? 'crud.title.edit' : 'crud.title.create', { name }),
  })
  if (!id.value) form.parentId = Number(query?.parentId) || 0
  if (id.value)
    try {
      fillForm(form, await topicApi.get(id.value))
    } catch (e) {
      return void (error.value = errorText(e))
    }
  if (form.parentId)
    topicApi.get(form.parentId).then(
      (r) => (parentRow.value = r),
      () => {}, // out of the caller's scope: its id shows
    )
  ready.value = true
})

async function submit() {
  if (submitting.value) return
  const parsed = topicCreate.safeParse(form)
  issues.value = parsed.error?.issues ?? []
  if (!parsed.success) return
  submitting.value = true
  error.value = ''
  try {
    if (id.value) await topicApi.update(id.value, parsed.data)
    else await topicApi.create(parsed.data)
    uni.showToast({ title: t(id.value ? 'crud.msg.updated' : 'crud.msg.created'), icon: 'none' })
    uni.navigateBack()
  } catch (e) {
    // a 400 (the rules), a 404 (gone, out of scope) belongs here; the request layer toasts the rest (409: a
    // unique value taken)
    if (e instanceof ApiError && (e.status === 400 || e.status === 404)) error.value = e.message
  } finally {
    submitting.value = false
  }
}
</script>
